import { defineConfig } from "oxfmt";
import ultracite from "ultracite/oxfmt";

// Ultracite's formatting preset. `bun run format` writes, `bun run format:check` fails on
// unformatted files. Oxfmt also skips what .gitignore lists.
export default defineConfig({
  ...ultracite,
  ignorePatterns: [
    ...ultracite.ignorePatterns,
    // Data files: snapshots and archives that scripts write and tests read.
    "data/**",
    "**/tests/fixtures/data/**",
    // Cached third-party documentation, regenerated by scripts/refresh-*.mjs.
    ".agent-sources/**",
    // Skills installed from skills-lock.json.
    ".agents/skills/**",
    "skills-lock.json",
    // Generated by `bun run generate:tamagui`.
    "apps/web/tamagui-prompt.md",
    // Vendored third-party code, kept identical to upstream.
    "tools/oxlint/oxlint-plugin-jev/**",
    "tools/oxlint/anti-slop/vendor/**",
    // Model prompts: reflowing them changes what the model reads.
    "packages/analyst/src/prompts/**",
  ],
});
